package cn.adc.appointments;
import cn.adc.shared.config.SourceStamp;import cn.adc.shared.db.JdbcTransactions;import cn.adc.shared.security.StaffSessionIdentityAdapter;import org.junit.jupiter.api.Test;import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.mock.web.MockHttpSession;import javax.sql.DataSource;import java.sql.*;import java.time.*;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class DoctorAppointmentTimelineTest {
 @Test void detailsAreBoundToDentistAndClinicAndNeverExposePatientIdentity()throws Exception{
  var ds=mock(DataSource.class);var c=mock(Connection.class);when(ds.getConnection()).thenReturn(c);when(c.createStatement()).thenReturn(mock(Statement.class));
  var root=mock(PreparedStatement.class);var rows=mock(ResultSet.class);when(root.executeQuery()).thenReturn(rows);when(rows.next()).thenReturn(true,false);when(rows.getLong(1)).thenReturn(87001L);when(rows.getInt(2)).thenReturn(2);when(rows.getObject(3,OffsetDateTime.class)).thenReturn(OffsetDateTime.parse("2026-11-21T09:00:00Z"));when(rows.getObject(4,OffsetDateTime.class)).thenReturn(OffsetDateTime.parse("2026-11-21T12:00:00Z"));
  var detail=mock(PreparedStatement.class);var appointments=mock(ResultSet.class);when(detail.executeQuery()).thenReturn(appointments);when(appointments.next()).thenReturn(true,false);when(appointments.getLong(1)).thenReturn(71002L);when(appointments.getObject(2,OffsetDateTime.class)).thenReturn(OffsetDateTime.parse("2026-11-21T10:00:00Z"));when(appointments.getObject(3,OffsetDateTime.class)).thenReturn(OffsetDateTime.parse("2026-11-21T10:27:00Z"));when(appointments.getString(4)).thenReturn("待到诊");
  when(c.prepareStatement(anyString())).thenAnswer(call->{String sql=call.getArgument(0);assertFalse(sql.contains("patient_name"));assertFalse(sql.contains("contact_information"));return sql.contains("SELECT a.appointment_id")?detail:root;});
  var request=new MockHttpServletRequest();var session=new MockHttpSession();request.setSession(session);session.setAttribute(StaffSessionIdentityAdapter.SESSION_ATTRIBUTE,new StaffSessionIdentityAdapter.VerifiedSession("SYNTHETIC dentist","SYNTHETIC",new SourceStamp("SYNTHETIC","1","fixture",Instant.now(),true)));
  var result=new CourseDentistSchedule(new JdbcTransactions(ds),81001,79001).read(request,null,true);assertEquals(200,result.getStatusCode().value());var item=result.getBody().path("items").get(0);assertEquals(1,item.path("appointmentCount").asInt());assertEquals("71002",item.path("appointments").get(0).path("appointmentId").asText());assertFalse(item.toString().contains("patientId"));verify(detail).setLong(3,81001);verify(detail).setLong(4,79001);verify(detail,never()).executeUpdate();
 }
}
